-- Owner4e7f6f26: retrieve hardcoded synthetic DB data for advisor analysis, not a webpage.
-- Global reference fixtures only. They contain no tenant, provider or account identifiers.
-- Generated from the existing deterministic calculator scenarios at d712387.
-- finance_api can read, but cannot insert/update/delete these seeded records.
CREATE TABLE advisor_demo_scenarios (
    scenario_id text NOT NULL,
    scenario_version text NOT NULL,
    seed_version text NOT NULL,
    payload jsonb NOT NULL CHECK (
        payload->>'synthetic' = 'true'
        AND payload->>'data_origin' = 'seeded_synthetic_db'
        AND payload->>'scenario_id' = scenario_id
        AND payload->>'scenario_version' = scenario_version
    ),
    sha256 text NOT NULL CHECK (sha256 ~ '^[a-f0-9]{64}$'),
    created_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (scenario_id, scenario_version)
);
GRANT SELECT ON advisor_demo_scenarios TO finance_api;
